import React from 'react';
import { useParams } from 'react-router-dom';

const ProductDetails = () => {
  const { productId } = useParams();

  // Mock data - In a real application, you might fetch the product details from an API
  const productsArr = [
    { id: 1, title: "English Songs", price: 1, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/hollywood1.jpg?raw=true" },
    { id: 2, title: "Instrumental", price: 2, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/instrumental.jpg?raw=true" },
    { id: 3, title: "Bollywood", price: 3, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/bollywood.jpeg?raw=true" },
    { id: 4, title: "Tamil songs", price: 1, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/tamil.jpg?raw=true" },
  ];

  const product = productsArr.find(p => p.id === parseInt(productId));

  if (!product) {
    return <div>Product not found</div>;
  }

  return (
    <div>
      <h2>{product.title}</h2>
      <img src={product.imageUrl} alt={product.title} style={{ width: '300px' }} />
      <p>Price: ${product.price}</p>
      <p>More details about the product...</p>
    </div>
  );
};

export default ProductDetails;
